-- Ricoh Event leads: recreate CRM schema + import
-- Run in Supabase SQL Editor (full replace)

drop table if exists public.crm_activity_logs cascade;
drop table if exists public.crm_contacts cascade;
drop table if exists public.crm_cases cascade;

create table public.crm_cases (
  id text primary key,
  customer_name text not null,
  partner text not null default 'Ricoh Partner',
  systems text[] not null default '{}',
  requirements text not null default '',
  quantity text not null default '',
  budget numeric not null default 0,
  amount numeric not null default 0,
  success_rate int not null default 20,
  target_closing_date date,
  stage text not null default 'new_lead'
    check (stage in (
      'new_lead','contacting','unreachable','appointment_set',
      'first_interview','quotation','follow_up','final_stage','confirmation','closed'
    )),
  close_reason text check (close_reason in ('disqualified','failed','won') or close_reason is null),
  notes text not null default '',
  ricoh_house text not null default '',
  ricoh_sales text not null default '',
  ricoh_consultant text not null default '',
  team_leader text not null default '',
  company_sales text not null default '',
  appointment_flag boolean not null default false,
  appointment_at timestamptz,
  appointment_confirmed boolean not null default false,
  meeting_done boolean not null default false,
  meeting_notes text not null default '',
  follow_up_opportunity boolean not null default false,
  next_follow_up_at date,
  lead_status text not null default 'Processing',
  source_event text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.crm_contacts (
  id text primary key,
  case_id text not null references public.crm_cases(id) on delete cascade,
  name text not null,
  title text not null default '',
  tel text not null default '',
  fax text not null default '',
  mobile text not null default '',
  email text not null default '',
  created_at timestamptz not null default now()
);

create table public.crm_activity_logs (
  id text primary key,
  case_id text not null references public.crm_cases(id) on delete cascade,
  contact_id text references public.crm_contacts(id) on delete set null,
  log_type text not null default 'remark',
  content text not null default '',
  happened_at timestamptz,
  created_at timestamptz not null default now()
);

create index crm_cases_stage_idx on public.crm_cases(stage);
create index crm_cases_sales_idx on public.crm_cases(ricoh_sales);
create index crm_contacts_case_idx on public.crm_contacts(case_id);
create index crm_logs_case_idx on public.crm_activity_logs(case_id);

alter table public.crm_cases enable row level security;
alter table public.crm_contacts enable row level security;
alter table public.crm_activity_logs enable row level security;

create policy crm_cases_all on public.crm_cases for all to anon, authenticated using (true) with check (true);
create policy crm_contacts_all on public.crm_contacts for all to anon, authenticated using (true) with check (true);
create policy crm_logs_all on public.crm_activity_logs for all to anon, authenticated using (true) with check (true);

